// ./src/App.js (enhanced sections)

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import SupportersCarousel from './components/SupportersCarousel';
import WorkWithUs from './WorkWithUs';
import AboutUs from './AboutUs';
import TheLab from './TheLab';

import ISText from './assets/IronpulseText.png';
import FBIcon from './assets/AstroAssault.png';
import PBS from './assets/ProjectBreakerScreen1.png';
import PFantom from './assets/ProjectPhantom.png';
import BTreas from './assets/BrowserTreasure.png';
import PFAlien from './assets/ProjectFallaceAlien.png';
import PhantomPath from './assets/ProjectPhantomPath.png';

// Animated Section
function AnimatedImageSection({ image, heading, paragraph, reverse = false, height = "650px" }) {
  const fadeLeft = { hidden: { opacity: 0, x: -60 }, visible: { opacity: 1, x: 0 } };
  const fadeRight = { hidden: { opacity: 0, x: 60 }, visible: { opacity: 1, x: 0 } };
  return (
    <section className={`relative w-full flex flex-col lg:flex-row ${reverse ? 'lg:flex-row-reverse' : ''}`} style={{ height }}>
      <div className="relative w-full lg:w-1/2 h-64 lg:h-full overflow-hidden">
        <motion.img
          src={image}
          alt={heading}
          className="absolute inset-0 w-full h-full object-cover rounded-xl hover:scale-105 transition-transform duration-500"
        />
        <div className="absolute inset-0 bg-gradient-to-r from-black via-black/50 to-black/0 rounded-xl" />
      </div>

      <motion.div
        className="relative w-full lg:w-1/2 px-6 py-12 flex flex-col justify-center text-left z-10 text-gray-100"
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, amount: 0.3 }}
        variants={reverse ? fadeLeft : fadeRight}
        transition={{ duration: 0.8 }}
      >
        <h2 className="text-3xl font-bold mb-4">{heading}</h2>
        <p className="text-lg">{paragraph}</p>
      </motion.div>
    </section>
  )
}

export default function App() {
  const [activeGame, setActiveGame] = useState(null);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);

  const mainCarousel = [
    { id: 'breaker', title: 'PROJECT BREAKER', cover: FBIcon, splashImages: [PBS], platforms: ['IOS','Android','Itch.io'], release:'2026', status:'In Development' },
    { id: 'fallace', title: 'PROJECT FALLACE', cover: PFAlien, splashImages: [PFAlien], platforms:['PC'], release:'2028', status:'Pre-production' },
    { id: 'phantom', title: 'PROJECT PHANTOM', cover: PhantomPath, splashImages:[PFantom], platforms:['PC','GOG','SWITCH'], release:'2027', status:'Pre-production' },
  ];

  useEffect(() => {
    const interval = setInterval(() => setCurrentSlide(prev => (prev + 1) % mainCarousel.length), 6000);
    return () => clearInterval(interval);
  }, [mainCarousel.length]);

  return (
    <Router>
      <AnimatePresence mode="wait">
        <Routes>
          <Route path="/" element={
            <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}>
              <div className="min-h-screen bg-black text-gray-100 antialiased tracking-wide">

                {/* HEADER */}
                <header className="w-full fixed z-50 top-0 left-0 px-6 py-8 flex items-center justify-between bg-gradient-to-b from-black to-transparent">
                  <img src={ISText} alt="Logo" className="w-40" />
                  <nav className="hidden md:flex gap-10 font-bold text-xs text-gray-300">
                    <a href="#games" className="hover:text-white">GAMES</a>
                    <a href="#updates" className="hover:text-white">NEWS</a>
                    <Link to="/the-lab" className="hover:text-white">THE LAB</Link>
                    <Link to="/work-with-us" className="hover:text-white">JOIN US</Link>
                    <Link to="/about-us" className="hover:text-white">ABOUT</Link>
                  </nav>
                </header>

                {/* HERO */}
                <section className="relative w-full h-screen overflow-hidden">
                  {mainCarousel.map((slide, index) => (
                    <motion.div
                      key={slide.id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: index === currentSlide ? 1 : 0 }}
                      transition={{ duration: 1 }}
                      className="absolute inset-0"
                    >
                      <img src={slide.splashImages[0]} alt={slide.title} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-gradient-to-b from-black/70 via-black/60 to-black/90" />
                      <div className="absolute inset-0 flex flex-col items-center justify-center text-center px-6">
                        <h1 className="text-5xl md:text-6xl font-bold tracking-widest mb-6">{slide.title}</h1>
                        <p className="text-gray-300 mb-8">{slide.status} • {slide.release}</p>
                      </div>
                    </motion.div>
                  ))}
                </section>

                {/* Animated Sections */}
                <AnimatedImageSection
                  image={PFantom}
                  heading="GAMES BEYOND DREAMS"
                  paragraph="We craft immersive worlds, bold narratives, and unforgettable gameplay."
                />

                <section id="games" className="max-w-7xl mx-auto px-6 py-24">
                  <h2 className="text-4xl font-bold text-center mb-16 tracking-wider">OUR GAMES</h2>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
                    {mainCarousel.map((g) => (
                      <motion.article key={g.id} whileHover={{scale:1.04}} className="bg-gray-900 rounded-2xl overflow-hidden shadow-2xl border border-white/5">
                        <img src={g.cover} alt={g.title} className="w-full h-56 object-cover" />
                        <div className="p-6 text-center">
                          <h4 className="text-lg font-semibold">{g.title}</h4>
                          <p className="text-sm text-gray-400 mt-2">{g.status}</p>
                        </div>
                      </motion.article>
                    ))}
                  </div>
                </section>

                {/* NEWS */}
                <AnimatedImageSection
                  image="https://images.unsplash.com/photo-1506744038136-46273834b3fb"
                  heading="LATEST NEWS"
                  paragraph="Stay up to date with our latest updates, releases, and announcements."
                  reverse={true}
                  height="550px"
                />

                {/* SUPPORTERS */}
                <AnimatedImageSection
                  image="https://images.unsplash.com/photo-1581092915363-1de1919b26db"
                  heading="OUR SUPPORTERS"
                  paragraph="Powered by community. Driven by passion."
                >
                  <div className="mt-12">
                    <SupportersCarousel speed={50} />
                  </div>
                </AnimatedImageSection>

              </div>
            </motion.div>
          }/>
          <Route path="/work-with-us" element={<WorkWithUs />} />
          <Route path="/about-us" element={<AboutUs />} />
          <Route path="/the-lab" element={<TheLab />} />
        </Routes>
      </AnimatePresence>
    </Router>
  );
}
